import React from 'react';
import { Typography, List } from 'antd';

const { Title, Paragraph } = Typography;

function Home() {
    const skills = [
        'JavaScript (ES6+)',
        'React, Redux, Context API',
        'HTML5, CSS3, Ant Design',
        'REST API, Axios, Git/GitHub',
        'Базові знання Node.js',
    ];

    return (
        <Typography>
            <Title level={2}>Привіт! Я, Половнєва Альона </Title>
            <Paragraph>
                Я Frontend-розробник із фокусом на створенні SPA за допомогою React та сучасних інструментів.
                Маю досвід у реалізації UI, роботі з API та адаптивному дизайні.
            </Paragraph>

            <Title level={4}>Навички:</Title>
            <List
                bordered
                dataSource={skills}
                renderItem={(item) => <List.Item>{item}</List.Item>}
                style={{ maxWidth: 500 }}
            />
        </Typography>
    );
}

export default Home;
